98	static void *handle_ssl_connection(void *data)
99	{
100	    int ret, len;
101	    thread_info_t *thread_info = (thread_info_t *) data;
102	    mbedtls_net_context *client_fd = &thread_info->client_fd;
103	    long int thread_id = (long int) pthread_self();
104	    unsigned char buf[1024];
105	    mbedtls_ssl_context ssl;
106	
107	    /* Make sure memory references are valid */
108	    mbedtls_ssl_init(&ssl);
109	
110	    mbedtls_printf("  [ #%ld ]  Setting up SSL/TLS data\n", thread_id);
111	
112	    /*
113	     * 4. Get the SSL context ready
114	     */
115	    if ((ret = mbedtls_ssl_setup(&ssl, thread_info->config)) != 0) {
116	        mbedtls_printf("  [ #%ld ]  failed: mbedtls_ssl_setup returned -0x%04x\n",
117	                       thread_id, (unsigned int) -ret);
118	        goto thread_exit;
119	    }
120	
121	    mbedtls_ssl_set_bio(&ssl, client_fd, mbedtls_net_send, mbedtls_net_recv, NULL);
122	
123	    /*
124	     * 5. Handshake
125	     */
126	    mbedtls_printf("  [ #%ld ]  Performing the SSL/TLS handshake\n", thread_id);
127	    fflush(stdout);
128	
129	    while ((ret = mbedtls_ssl_handshake(&ssl)) != 0) {
130	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
131	            mbedtls_printf("  [ #%ld ]  failed: mbedtls_ssl_handshake returned -0x%04x\n",
132	                           thread_id, (unsigned int) -ret);
133	            goto thread_exit;
134	        }
135	    }
136	
137	    mbedtls_printf("  [ #%ld ]  ok\n", thread_id);
138	
139	    /*
140	     * 6. Read the HTTP Request
141	     */
142	    mbedtls_printf("  [ #%ld ]  < Read from client\n", thread_id);
143	    fflush(stdout);
144	
145	    do {
146	        len = sizeof(buf) - 1;
147	        memset(buf, 0, sizeof(buf));
148	        ret = mbedtls_ssl_read(&ssl, buf, len);
149	
150	        if (ret == MBEDTLS_ERR_SSL_WANT_READ || ret == MBEDTLS_ERR_SSL_WANT_WRITE) {
151	            continue;
152	        }
153	
154	        if (ret <= 0) {
155	            switch (ret) {
156	                case MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY:
157	                    mbedtls_printf("  [ #%ld ]  connection was closed gracefully\n",
158	                                   thread_id);
159	                    goto thread_exit;
160	
161	                case MBEDTLS_ERR_NET_CONN_RESET:
162	                    mbedtls_printf("  [ #%ld ]  connection was reset by peer\n",
163	                                   thread_id);
164	                    goto thread_exit;
165	
166	                default:
167	                    mbedtls_printf("  [ #%ld ]  mbedtls_ssl_read returned -0x%04x\n",
168	                                   thread_id, (unsigned int) -ret);
169	                    goto thread_exit;
170	            }
171	        }
172	
173	        len = ret;
174	        mbedtls_printf("  [ #%ld ]  %d bytes read\n=====\n%s\n=====\n",
175	                       thread_id, len, (char *) buf);
176	        fflush(stdout);
177	
178	        if (ret > 0) {
179	            break;
180	        }
181	    } while (1);
182	
183	    /*
184	     * 7. Write the 200 Response
185	     */
186	    mbedtls_printf("  [ #%ld ]  > Write to client:\n", thread_id);
187	    fflush(stdout);
188	
189	    len = sprintf((char *) buf, HTTP_RESPONSE,
190	                  mbedtls_ssl_get_ciphersuite(&ssl));
191	
192	    while ((ret = mbedtls_ssl_write(&ssl, buf, len)) <= 0) {
193	        if (ret == MBEDTLS_ERR_NET_CONN_RESET) {
194	            mbedtls_printf("  [ #%ld ]  failed: peer closed the connection\n",
195	                           thread_id);
196	            goto thread_exit;
197	        }
198	
199	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
200	            mbedtls_printf("  [ #%ld ]  failed: mbedtls_ssl_write returned -0x%04x\n",
201	                           thread_id, (unsigned int) ret);
202	            goto thread_exit;
203	        }
204	    }
205	
206	    len = ret;
207	    mbedtls_printf("  [ #%ld ]  %d bytes written\n=====\n%s\n=====\n",
208	                   thread_id, len, (char *) buf);
209	    fflush(stdout);
210	
